-- TOC entry 326 (class 1255 OID 59275)
-- Name: fn_citas_delete_by_plan(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_citas_delete_by_plan(_idplan integer, _idpaciente integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM cita
     WHERE idpaciente = _idpaciente
       AND observaciones ILIKE 'Plan #' || _idplan || ' - Sesión %';
END;
$$;


--
-- TOC entry 338 (class 1255 OID 59272)
-- Name: fn_plan_sync_estado(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_plan_sync_estado(_idplan integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total  INT;
    v_hechas INT;
BEGIN
    SELECT COUNT(*), COUNT(*) FILTER (WHERE estado = 'COMPLETADA'::sesion_estado)
      INTO v_total, v_hechas
      FROM plan_sesion
     WHERE idplan = _idplan;

    UPDATE plan_sesiones ps
       SET sesiones_completadas = COALESCE(v_hechas, 0),
           estado = CASE
                      WHEN COALESCE(v_hechas,0) >= COALESCE(ps.total_sesiones,0)
                           AND ps.total_sesiones IS NOT NULL
                           THEN 'FINALIZADO'::plan_estado
                      WHEN ps.estado = 'CANCELADO'::plan_estado
                           THEN 'CANCELADO'::plan_estado
                      ELSE 'ACTIVO'::plan_estado
                    END,
           fecha_fin = CASE
                         WHEN COALESCE(v_hechas,0) >= COALESCE(ps.total_sesiones,0)
                              AND ps.total_sesiones IS NOT NULL
                              THEN COALESCE(ps.fecha_fin, CURRENT_DATE)
                         WHEN ps.estado = 'CANCELADO'::plan_estado
                              THEN NULL
                         ELSE NULL
                       END
     WHERE ps.idplan = _idplan;
END;
$$;


--
-- TOC entry 340 (class 1255 OID 59278)
-- Name: trg_plan_cancelado_delete_citas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_plan_cancelado_delete_citas() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_idpac INT;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.estado = 'CANCELADO'::plan_estado THEN
        SELECT idpaciente INTO v_idpac FROM plan_sesiones WHERE idplan = NEW.idplan;
        DELETE FROM cita
         WHERE idpaciente = v_idpac
           AND observaciones ILIKE 'Plan #' || NEW.idplan || ' - Sesión %';
    END IF;
    RETURN NEW;
END;
$$;


--
-- TOC entry 339 (class 1255 OID 59273)
-- Name: trg_plan_sesion_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_plan_sesion_sync() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP IN ('INSERT','UPDATE') THEN
        PERFORM fn_plan_sync_estado(NEW.idplan);
    ELSIF TG_OP = 'DELETE' THEN
        PERFORM fn_plan_sync_estado(OLD.idplan);
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- TOC entry 341 (class 1255 OID 59276)
-- Name: trg_sesion_cancelada_delete_cita(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_sesion_cancelada_delete_cita() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    _like TEXT;
BEGIN
    -- Si el estado de la sesión quedó en "CANCELADA" o "ANULADA" (si existiera),
    -- borramos la cita asociada (por convención en "observaciones").
    IF TG_OP = 'UPDATE'
       AND NEW.estado::text IN ('CANCELADA', 'ANULADA') THEN
        _like := 'Plan #' || NEW.idplan || ' - Sesión ' || NEW.nro || '%';
        DELETE FROM cita
         WHERE idpaciente = (SELECT idpaciente FROM plan_sesiones WHERE idplan = NEW.idplan)
           AND observaciones ILIKE _like;
    END IF;
    RETURN NEW;
END;
$$;


