-- TOC entry 309 (class 1259 OID 51030)
-- Name: vw_historial_paciente; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_historial_paciente AS
 SELECT pr.idpaciente,
    pr.fecha,
    'PROCEDIMIENTO'::text AS tipo_evento,
    NULL::integer AS idventa,
    NULL::integer AS idventadet,
    pr.id AS idprocedimiento,
    pr.iditem,
    i.nombre AS item_nombre,
    (1)::numeric(12,2) AS cantidad,
    NULL::numeric(12,2) AS precio_unitario,
    NULL::numeric(12,2) AS subtotal,
    (0)::numeric(12,2) AS saldo,
    pr.comentario AS observacion,
    'Estado'::text AS estado
   FROM (public.procedimiento pr
     LEFT JOIN public.item i ON ((i.iditem = pr.iditem)))
UNION ALL
 SELECT v.idpaciente,
    v.fecha,
    'VENTA'::text AS tipo_evento,
    v.idventa,
    vd.idventadet,
    NULL::integer AS idprocedimiento,
    vd.iditem,
    i.nombre AS item_nombre,
    vd.cantidad,
    vd.preciounitario AS precio_unitario,
    ((((vd.cantidad)::numeric * vd.preciounitario) - COALESCE(vd.descuento, (0)::numeric)))::numeric(12,2) AS subtotal,
    (COALESCE(v.saldo, (0)::numeric))::numeric(12,2) AS saldo,
    v.observaciones AS observacion,
    v.estadoventa AS estado
   FROM ((public.venta v
     JOIN public.venta_detalle vd ON ((vd.idventa = v.idventa)))
     LEFT JOIN public.item i ON ((i.iditem = vd.iditem)));


