CREATE VIEW public.vw_produccion_prof_dia AS
 SELECT ps.idterapeuta AS idprofesional,
    date(ps.fecha_realizada) AS dia,
    count(*) AS atenciones,
    count(DISTINCT pl.idpaciente) AS pacientes_unicos
   FROM (public.plan_sesion ps
     JOIN public.plan_sesiones pl ON ((pl.idplan = ps.idplan)))
  WHERE ((ps.estado = 'COMPLETADA'::public.sesion_estado) AND (ps.idterapeuta IS NOT NULL) AND (ps.fecha_realizada IS NOT NULL))
  GROUP BY ps.idterapeuta, (date(ps.fecha_realizada));


--
