-- Name: vw_saldo_cliente_detalle; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_saldo_cliente_detalle AS
 SELECT v.idventa,
    v.fecha,
    v.nro_factura,
    v.idpaciente,
    (((p.apellido)::text || ', '::text) || (p.nombre)::text) AS paciente,
    v.montototal AS total_venta,
    v.saldo AS saldo_venta,
    i.nombre AS item,
    vd.cantidad,
    vd.preciounitario,
    COALESCE(vd.descuento, (0)::numeric) AS descuento,
    (((vd.cantidad)::numeric * vd.preciounitario) - COALESCE(vd.descuento, (0)::numeric)) AS subtotal_item
   FROM (((public.venta v
     JOIN public.paciente p ON ((p.idpaciente = v.idpaciente)))
     JOIN public.venta_detalle vd ON ((vd.idventa = v.idventa)))
     JOIN public.item i ON ((i.iditem = vd.iditem)))
  WHERE ((v.saldo > (0)::numeric) AND ((v.estadoventa IS NULL) OR (upper((v.estadoventa)::text) <> ALL (ARRAY['ANULADA'::text, 'ANULADO'::text, 'CANCELADA'::text]))));


--
-- TOC entry 310 (class 1259 OID 51036)
-- Name: vw_saldo_cliente_resumen; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_saldo_cliente_resumen AS
 SELECT v.idventa,
    v.fecha,
    v.nro_factura,
    v.idpaciente,
    (((p.apellido)::text || ', '::text) || (p.nombre)::text) AS paciente,
    v.montototal AS total,
    v.saldo,
    json_agg(json_build_object('item', i.nombre, 'cantidad', vd.cantidad, 'precio', vd.preciounitario, 'descuento', COALESCE(vd.descuento, (0)::numeric), 'subtotal', (((vd.cantidad)::numeric * vd.preciounitario) - COALESCE(vd.descuento, (0)::numeric))) ORDER BY i.nombre) AS detalle_items
   FROM (((public.venta v
     JOIN public.paciente p ON ((p.idpaciente = v.idpaciente)))
     JOIN public.venta_detalle vd ON ((vd.idventa = v.idventa)))
     JOIN public.item i ON ((i.iditem = vd.iditem)))
  WHERE ((v.saldo > (0)::numeric) AND ((v.estadoventa IS NULL) OR (upper((v.estadoventa)::text) <> ALL (ARRAY['ANULADA'::text, 'ANULADO'::text, 'CANCELADA'::text]))))
  GROUP BY v.idventa, v.fecha, v.nro_factura, v.idpaciente, p.apellido, p.nombre, v.montototal, v.saldo;


