--
-- TOC entry 5450 (class 2618 OID 59283)
-- Name: vw_planes_por_paciente _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.vw_planes_por_paciente AS
 SELECT ps.idplan,
    pt.nombre AS plan_tipo,
    (count(s.idsesion))::integer AS total,
    (count(*) FILTER (WHERE (s.estado = 'COMPLETADA'::public.sesion_estado)))::integer AS hechas,
    (GREATEST((count(s.idsesion) - count(*) FILTER (WHERE (s.estado = 'COMPLETADA'::public.sesion_estado))), (0)::bigint))::integer AS restan,
    ps.estado,
    ps.fecha_inicio,
    ps.fecha_fin,
    vd.idventa
   FROM (((public.plan_sesiones ps
     JOIN public.plan_tipo pt ON ((pt.idplantipo = ps.idplantipo)))
     LEFT JOIN public.plan_sesion s ON ((s.idplan = ps.idplan)))
     LEFT JOIN public.venta_detalle vd ON ((vd.idventadet = ps.idventadet)))
  GROUP BY ps.idplan, pt.nombre, vd.idventa;


